import{_ as t,o as a,c as r,a2 as n}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"Literature reviews","description":"","frontmatter":{},"headers":[],"relativePath":"guide/reviews.md","filePath":"guide/reviews.md","lastUpdated":1791997268000}'),o={name:"guide/reviews.md"};function i(s,e,d,c,l,h){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="literature-reviews" tabindex="-1">Literature reviews <a class="header-anchor" href="#literature-reviews" aria-label="Permalink to &quot;Literature reviews&quot;">​</a></h1><p><strong>Experimental.</strong> Turn selected abstract evidence into a thematic outline and an editable draft with citations.</p><p>The feature uses available papers and abstracts, not automatically read full-text PDFs. Check the draft against original research.</p><h2 id="module-and-evidence" tabindex="-1">Module and evidence <a class="header-anchor" href="#module-and-evidence" aria-label="Permalink to &quot;Module and evidence&quot;">​</a></h2><p>Review contains Papers, Outline, Draft, and Citation evidence. Expand the model controls within the review page to configure its model; it cannot change during generation. Its sidebar lists reviews only. Citation evidence brings together paragraph citations and paper relations. New reviews preserve available source-map snapshots; older reviews may still depend on the source search.</p><h2 id="_1-select-evidence" tabindex="-1">1. Select evidence <a class="header-anchor" href="#_1-select-evidence" aria-label="Permalink to &quot;1. Select evidence&quot;">​</a></h2><p>Start from selected results, or choose <strong>Reviews → New review</strong> and an existing search.</p><p>Choose <strong>2–100 papers</strong> with informative abstracts and a coherent relationship to the topic. More papers do not automatically mean better evidence. Records without meaningful research content may not contribute to the draft.</p><p>Online reviews require login and a saved source search; Community stores them locally.</p><h2 id="_2-set-the-scope" tabindex="-1">2. Set the scope <a class="header-anchor" href="#_2-set-the-scope" aria-label="Permalink to &quot;2. Set the scope&quot;">​</a></h2><p>Provide a topic and select English or Chinese, then Short, Standard, or Detailed.</p><p>Default chapter counts are <strong>1, 3, and 6</strong>, with a custom range of <strong>1–14</strong>. This is not a fixed word-count guarantee; the evidence and outline determine what can be written.</p><p>Configure a writing model in Community or with your own key online, or choose an allowed model in PaperSeek Service.</p><h2 id="_3-check-the-outline" tabindex="-1">3. Check the outline <a class="header-anchor" href="#_3-check-the-outline" aria-label="Permalink to &quot;3. Check the outline&quot;">​</a></h2><p>Review the themes, chapter structure, paragraph plans, and assigned papers. Look for omitted perspectives and a scope broader than the evidence supports.</p><p>Use <strong>Save outline</strong> to save edits without starting a writing task. Use <strong>Confirm outline and write</strong> or <strong>Save outline and write</strong> when ready to generate the draft. Leaving with unsaved edits prompts you to keep editing or discard them.</p><h2 id="_4-read-and-revise" tabindex="-1">4. Read and revise <a class="header-anchor" href="#_4-read-and-revise" aria-label="Permalink to &quot;4. Read and revise&quot;">​</a></h2><p>Edit text, rewrite an individual section, and inspect available versions. A changed outline does not automatically make the old draft match it; check the current version and task state.</p><p>Choose numbered or Harvard author–year citation display. Exports follow that choice.</p><p>Evidence checks can flag missing or inconsistent support. They do not certify scientific truth. Read cited papers before relying on the claims.</p><h2 id="_5-export" tabindex="-1">5. Export <a class="header-anchor" href="#_5-export" aria-label="Permalink to &quot;5. Export&quot;">​</a></h2><ul><li><strong>Markdown</strong> for further editing.</li><li><strong>Word (.docx)</strong> for document workflows.</li><li><strong>BibTeX</strong> for the references.</li></ul><h2 id="if-generation-stops" tabindex="-1">If generation stops <a class="header-anchor" href="#if-generation-stops" aria-label="Permalink to &quot;If generation stops&quot;">​</a></h2><p>Inspect the current or latest task separately from the saved draft. A stopped task does not erase the outline or completed chapters. Model access, credit, timeouts, and structured-response errors can interrupt an outline or section. Fix the cause and retry the affected operation instead of creating duplicate reviews.</p><p>Refreshing reconnects to saved state; it does not restart generation. Online writing shares the <a href="./../online/#when-your-task-is-queued">execution queue</a> with searches.</p>',25)])])}const g=t(o,[["render",i]]);export{u as __pageData,g as default};
